<script setup>defineProps({columns:Array,rows:Array})</script>
<template><div v-if="!rows?.length" class="empty">暂无数据</div><div v-else class="table-wrap"><table><thead><tr><th v-for="c in columns" :key="c.key">{{c.label}}</th></tr></thead><tbody><tr v-for="(row,i) in rows" :key="row.id||i"><td v-for="c in columns" :key="c.key" :class="c.class?.(row[c.key])"><button v-if="c.action" class="table-link" @click="c.action(row)">{{c.format?c.format(row[c.key],row):row[c.key]??'—'}}</button><template v-else>{{c.format?c.format(row[c.key],row):row[c.key]??'—'}}</template></td></tr></tbody></table></div></template>
